(function executeRule(current, previous) {

    // 1. Ensure this is only for 'Trade' customers
    if (current.customer_type + '' !== 'Trade') return;

    // 2. Ensure it only runs exactly when the state changes to Approved
    if (current.state + '' !== 'Approved' || previous.state + '' === 'Approved') return;

    var segment = current.segment + '';
    var creditSegment = '';

    // 3. Map the segments
    if (segment === 'Cement') creditSegment = 'GIL';
    else if (segment === 'RMC') creditSegment = 'URMX';
    else if (segment === 'BPD') creditSegment = 'GIL';

    if (!creditSegment) {
        gs.error('CLM SAP Writeback Queue: Unrecognized segment "' + segment + '" for request ' + current.number);
        return;
    }

    // 4. Initialize the send back queue record
    var q = new GlideRecord('x_birl3_clm_clm_servicenow_to_sap_send_back');
    q.initialize();

    q.u_request = current.sys_id;
    q.u_customer_code = current.customer;

    // ==========================================
    // 5. ROBUST LIMIT FETCHING LOGIC
    // ==========================================
    // Try getting the value both without and with the 'u_' prefix
    var rawLimit = current.getValue('approved_limit') || current.getValue('u_approved_limit') || 0;

    // If it's a currency field, it might return a string like "INR;210000". This extracts just the number.
    if (typeof rawLimit === 'string' && rawLimit.indexOf(';') > -1) {
        rawLimit = rawLimit.split(';')[1];
    }

    // Force the value to a decimal/float to prevent String->Integer data type mismatches 
    q.u_approved_code_limit = parseFloat(rawLimit) || 0;
    // ==========================================

    q.u_next_review_date = current.next_review_date;
    q.u_credit_segment = creditSegment;
    q.u_status = 'Pending';
    q.u_attempt_count = 0;

    q.insert();

    gs.info('CLM SAP Writeback Queue: inserted row for ' + current.number +
             ' | segment=' + creditSegment +
             ' | rawLimit Found=' + rawLimit + 
             ' | final_approved_code_limit=' + q.u_approved_code_limit);

})(current, previous);
